// Market Research Agent
const marketResearch = {
  agent: 'market_research',
  task: 'Identificar mercado objetivo y clientes ideales',
  niche: $input.item.json.niche,
  industry: $input.item.json.industry
};

return marketResearch;

// Content Creator Agent
const contentCreation = {
  agent: 'content_creator',
  task: 'Crear contenido persuasivo para outreach',
  targetMarket: $input.item.json.targetMarket,
  valueProposition: $input.item.json.valueProposition
};

return contentCreation;

// Sales Specialist Agent
const salesStrategy = {
  agent: 'sales_specialist',
  task: 'Ejecutar campaña de prospección',
  content: $input.item.json.content,
  prospects: $input.item.json.prospects
};

return salesStrategy;

// QA Validator Agent
const validation = {
  agent: 'qa_validator',
  task: 'Validar todos los outputs antes de entregar',
  workToValidate: {
    marketResearch: $node['Market Research Agent'].json,
    content: $node['Content Creator Agent'].json,
    salesStrategy: $node['Sales Specialist Agent'].json
  }
};

return validation;
